    { id: 4, title: 'Upper', completed: true, priority: 'High', due_date: '2024-03-01' },
    { id: 5, title: 'After', completed: false, priority: 'Low', due_date: '2024-03-02' },
  ] };
  const original = structuredClone(pending.tasks);
