import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const reservation = createServer();
reservation.listen(0);
await once(reservation, 'listening');
const port = reservation.address().port;
await new Promise(resolve => reservation.close(resolve));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'launch.sqlite') },
  detached: true, stdio: 'ignore',
});
try {
  let response;
  for (let attempt = 0; attempt < 100; attempt++) {
    try { response = await fetch("'`http://127.0.0.1:${port}/health`); break; }
    catch { await new Promise(resolve => setTimeout(resolve, 25)); }
  }
  assert.equal(response?.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start with PORT and DB_PATH: health contract passed');
} finally {
  const exit = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exit;
  await rm(directory, { recursive: true, force: true });
}
